type parsedFlags struct {
	boolVals map[string]bool
	strVals map[string]string
	intVals map[string]int64
	stringsVals map[string][]string
	changed map[string]bool
}

func newParsedFlags() *parsedFlags {
	p := &parsedFlags{
		boolVals: map[string]bool{},
		strVals: map[string]string{},
		intVals: map[string]int64{},
		stringsVals: map[string][]string{},
		changed: map[string]bool{},
	}
	// defaults
	n := int64(runtime.NumCPU())
	p.intVals["depth"] = 0
	p.intVals["max-cores"] = n
	p.intVals["top"] = 0
	p.strVals["config-file"] = ""
	p.strVals["db"] = ""
	p.strVals["ignore-from"] = ""
	p.strVals["input-file"] = ""
	p.strVals["log-file"] = "/dev/null"
	p.strVals["max-age"] = ""
	p.strVals["min-age"] = ""
	p.strVals["since"] = ""
	p.strVals["until"] = ""
	p.strVals["output-file"] = ""
	p.stringsVals["exclude-type"] = []string{}
	p.stringsVals["type"] = []string{}
	p.stringsVals["ignore-dirs"] = []string{"/proc", "/dev", "/sys", "/run"}
	p.stringsVals["ignore-dirs-pattern"] = []string{}
	return p
}

func parseArgs(args []string) (*parsedFlags, []string, error) {
	p := newParsedFlags()
	var positionals []string
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			positionals = append(positionals, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			// long flag
			nameVal := arg[2:]
			var name, val string
			var hasVal bool
			if eq := strings.Index(nameVal, "="); eq >= 0 {
				name = nameVal[:eq]
				val = nameVal[eq+1:]
				hasVal = true
			} else {
				name = nameVal
				hasVal = false
			}
			def, ok := longToDef[name]
			if !ok {
				return nil, nil, fmt.Errorf("unknown flag: --%s", name)
			}
			switch def.typ {
			case "bool":
				if hasVal {
					b, err := strconv.ParseBool(val)
					if err != nil {
						return nil, nil, fmt.Errorf("invalid argument %q for %q flag: %v", val, flagDisplay(name), err)
					}
					p.boolVals[name] = b
					p.changed[name] = true
				} else {
					p.boolVals[name] = true
					p.changed[name] = true
				}
				i++
			case "string":
				var v string
				if hasVal {
					v = val
				} else {
					if i+1 >= len(args) {
						return nil, nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					v = args[i+1]
					i += 2
					p.strVals[name] = v
					p.changed[name] = true
					continue
				}
				p.strVals[name] = v
				p.changed[name] = true
				i++
			case "int":
				var v string
				if hasVal {
					v = val
				} else {
					if i+1 >= len(args) {
						return nil, nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					v = args[i+1]
					i += 2
					iv, err := strconv.ParseInt(v, 0, 64)
					if err != nil {
						return nil, nil, fmt.Errorf("invalid argument %q for %q flag: %v", v, flagDisplay(name), err)
					}
					p.intVals[name] = iv
					p.changed[name] = true
					continue
				}
				iv, err := strconv.ParseInt(v, 0, 64)
				if err != nil {
					return nil, nil, fmt.Errorf("invalid argument %q for %q flag: %v", v, flagDisplay(name), err)
				}
				p.intVals[name] = iv
				p.changed[name] = true
				i++
			case "strings":
				var v string
				if hasVal {
					v = val
				} else {
					if i+1 >= len(args) {
						return nil, nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					v = args[i+1]
					i += 2
					parts := splitStrings(v)
					p.stringsVals[name] = append(p.stringsVals[name], parts...)
					p.changed[name] = true
					continue
				}
				parts := splitStrings(v)
				p.stringsVals[name] = append(p.stringsVals[name], parts...)
				p.changed[name] = true
				i++
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 && arg != "-" {
			// shorthand(s)
			body := arg[1:]
			j := 0
			consumedNext := false
			for j < len(body) {
				ch := string(body[j])
				long, ok := shortToLong[ch]
				if !ok {
					// unknown: report suffix from j
					suffix := body[j:]
					return nil, nil, fmt.Errorf("unknown shorthand flag: '%s' in -%s", ch, suffix)
				}
				def := longToDef[long]
				rest := ""
				if j+1 < len(body) {
					rest = body[j+1:]
				}
				switch def.typ {
				case "bool":
					if strings.HasPrefix(rest, "=") {
						v := rest[1:]
						b, err := strconv.ParseBool(v)
						if err != nil {
							return nil, nil, fmt.Errorf("invalid argument %q for %q flag: %v", v, flagDisplay(long), err)
						}
						p.boolVals[long] = b
						p.changed[long] = true
						// consume rest
						j = len(body)
					} else {
						p.boolVals[long] = true
						p.changed[long] = true
						j++
					}
				case "string":
					var v string
					if strings.HasPrefix(rest, "=") {
						v = rest[1:]
						p.strVals[long] = v
						p.changed[long] = true
						j = len(body)
					} else if rest != "" {
						v = rest
						p.strVals[long] = v
						p.changed[long] = true
						j = len(body)
					} else {
						if i+1 >= len(args) {
							return nil, nil, fmt.Errorf("flag needs an argument: '%s' in -%s", ch, ch)
						}
						v = args[i+1]
						p.strVals[long] = v
						p.changed[long] = true
						consumedNext = true
						j = len(body)
					}
				case "int":
					var v string
					if strings.HasPrefix(rest, "=") {
						v = rest[1:]
						iv, err := strconv.ParseInt(v, 0, 64)
						if err != nil {
							return nil, nil, fmt.Errorf("invalid argument %q for %q flag: %v", v, flagDisplay(long), err)
						}
						p.intVals[long] = iv
						p.changed[long] = true
						j = len(body)
					} else if rest != "" {
						v = rest
						iv, err := strconv.ParseInt(v, 0, 64)
						if err != nil {
							return nil, nil, fmt.Errorf("invalid argument %q for %q flag: %v", v, flagDisplay(long), err)
						}
						p.intVals[long] = iv
						p.changed[long] = true
						j = len(body)
					} else {
						if i+1 >= len(args) {
							return nil, nil, fmt.Errorf("flag needs an argument: '%s' in -%s", ch, ch)
						}
						v = args[i+1]
						iv, err := strconv.ParseInt(v, 0, 64)
						if err != nil {
							return nil, nil, fmt.Errorf("invalid argument %q for %q flag: %v", v, flagDisplay(long), err)
						}
						p.intVals[long] = iv
						p.changed[long] = true
						consumedNext = true
						j = len(body)
					}
				case "strings":
					var v string
					if strings.HasPrefix(rest, "=") {
						v = rest[1:]
						parts := splitStrings(v)
						p.stringsVals[long] = append(p.stringsVals[long], parts...)
						p.changed[long] = true
						j = len(body)
					} else if rest != "" {
						v = rest
						// check if rest starts with =? already handled
						// For -i/tmp, rest is /tmp, value
						// But need to handle -i=/tmp? rest is =/tmp, handled above
						parts := splitStrings(v)
						p.stringsVals[long] = append(p.stringsVals[long], parts...)
						p.changed[long] = true
						j = len(body)
					} else {
						if i+1 >= len(args) {
							return nil, nil, fmt.Errorf("flag needs an argument: '%s' in -%s", ch, ch)
						}
						v = args[i+1]
						parts := splitStrings(v)
						p.stringsVals[long] = append(p.stringsVals[long], parts...)
						p.changed[long] = true
						consumedNext = true
						j = len(body)
					}
				}
			}
			i++
			if consumedNext {
				i++
			}
		} else {
			positionals = append(positionals, arg)
			i++
		}
	}
	return p, positionals, nil
}

func splitStrings(s string) []string {
	if s == "" {
		return []string{}
	}
	parts := strings.Split(s, ",")
	var out []string
	for _, p := range parts {
		// pflag strings: trims? Actually it keeps as is? For empty? Let's keep non-empty? But if value is ""? For --type ""? That would be []? Need to handle.
		// For our purposes, split and keep each (even empty? but empty would be ignored)
		// pflag for strings: splits by comma, no trimming? We'll trim spaces?
		// To match original, we should not trim? But type with spaces? Unlikely.
		// We'll keep as is, but filter empty? If s=="" already handled.
		out = append(out, p)
	}
	return out
}
