	}
	// Parse line by line
	lines := strings.Split(string(data), "\n")
	// For list handling, we need to collect
	type listState struct {
		key string
		items []string
	}
	var curList *listState
	flush := func() {
		if curList == nil {
			return
		}
		key := curList.key
		items := curList.items
		// map yaml key to flag
		switch key {
		case "ignore-dirs":
			if !p.changed["ignore-dirs"] {
				p.stringsVals["ignore-dirs"] = items
