func writeConfigFile(path string, p *parsedFlags) error {
	// Ensure dir exists? Original errors if dir doesn't exist, not create.
	// Build content matching original template
	getBoolStr := func(name string) string {
		if getBool(p, name) {
			return "true"
		}
		return "false"
	}
	_ = getBoolStr
	// ignore-dirs
	ignoreDirs := getStrings(p, "ignore-dirs")
	ignorePatterns := getStrings(p, "ignore-dirs-pattern")
	typeList := getStrings(p, "type")
	excludeList := getStrings(p, "exclude-type")
	formatList := func(items []string) string {
		if len(items) == 0 {
			return "[]"
		}
		var sb strings.Builder
		sb.WriteString("\n")
		for _, it := range items {
			sb.WriteString("    - " + it + "\n")
		}
		// trim trailing newline? Original ends with newline after last item, then next key. We'll keep as is but need to handle: for non-empty, they show as multiline without [].
		// Our builder adds newline at start and after each, need to remove last newline? Actually original for non-empty shows:
		// ignore-dirs:
		//     - /proc
		//     ...
		// So after colon, newline, then items. Good.
		s := sb.String()
		// remove trailing \n? Original has newline after last item, then next key on new line. So keep trailing \n but not extra?
		// sb ends with \n, good. Remove leading \n? No, we added leading \n to separate? Actually we need "ignore-dirs:\n    - ..."
		// Our sb starts with \n, so "ignore-dirs:" + sb would be "ignore-dirs:\n    - ...\n"
		// That's correct. But we return sb without the key, so caller does key+":"+sb? Let's handle differently.
		return strings.TrimSuffix(s, "\n")
	}
	_ = formatList
	var sb strings.Builder
	sb.WriteString("style:\n")
	sb.WriteString("    footer:\n")
	sb.WriteString("        text-color: '#000000'\n")
	sb.WriteString("        background-color: '#2479D0'\n")
	sb.WriteString("        number-color: '#FFFFFF'\n")
	sb.WriteString("    selected-row:\n")
	sb.WriteString("        text-color: \"\"\n")
	sb.WriteString("        background-color: \"\"\n")
	sb.WriteString("    result-row:\n")
	sb.WriteString("        number-color: '#e67100'\n")
	sb.WriteString("        directory-color: '#3498db'\n")
	sb.WriteString("    header:\n")
	sb.WriteString("        text-color: '#000000'\n")
	sb.WriteString("        background-color: '#2479D0'\n")
	sb.WriteString("        hidden: false\n")
	sb.WriteString("    progress-modal:\n")
	sb.WriteString("        current-item-path-max-len: 0\n")
	sb.WriteString("    use-old-size-bar: false\n")
	sb.WriteString("sorting:\n")
	sb.WriteString("    by: \"\"\n")
	sb.WriteString("    order: \"\"\n")
	sb.WriteString(fmt.Sprintf("log-file: %s\n", getString(p, "log-file")))
	// input-file, output-file, ignore-from-file: if empty, show "" else value?
	formatStr := func(s string) string {
		if s == "" {
			return `""`
		}
		return s
	}
	sb.WriteString(fmt.Sprintf("input-file: %s\n", formatStr(getString(p, "input-file"))))
	sb.WriteString(fmt.Sprintf("output-file: %s\n", formatStr(getString(p, "output-file"))))
	sb.WriteString(fmt.Sprintf("ignore-from-file: %s\n", formatStr(getString(p, "ignore-from"))))
	if len(ignoreDirs) == 0 {
		sb.WriteString("ignore-dirs: []\n")
	} else {
		sb.WriteString("ignore-dirs:\n")
		for _, it := range ignoreDirs {
			sb.WriteString("    - " + it + "\n")
		}
	}
	if len(ignorePatterns) == 0 {
		sb.WriteString("ignore-dir-patterns: []\n")
	} else {
		sb.WriteString("ignore-dir-patterns:\n")
		for _, it := range ignorePatterns {
			sb.WriteString("    - " + it + "\n")
		}
	}
	if len(typeList) == 0 {
		sb.WriteString("type: []\n")
	} else {
		sb.WriteString("type:\n")
		for _, it := range typeList {
			sb.WriteString("    - " + it + "\n")
		}
	}
	if len(excludeList) == 0 {
		sb.WriteString("exclude-type: []\n")
	} else {
		sb.WriteString("exclude-type:\n")
		for _, it := range excludeList {
			sb.WriteString("    - " + it + "\n")
		}
	}
	sb.WriteString(fmt.Sprintf("max-cores: %d\n", getInt(p, "max-cores")))
	sb.WriteString(fmt.Sprintf("top: %d\n", getInt(p, "top")))
	sb.WriteString(fmt.Sprintf("depth: %d\n", getInt(p, "depth")))
	sb.WriteString(fmt.Sprintf("sequential-scanning: %s\n", boolToStr(getBool(p, "sequential"))))
	sb.WriteString(fmt.Sprintf("show-apparent-size: %s\n", boolToStr(getBool(p, "show-apparent-size"))))
	sb.WriteString(fmt.Sprintf("show-relative-size: %s\n", boolToStr(getBool(p, "show-relative-size"))))
	sb.WriteString(fmt.Sprintf("show-annexed-size: %s\n", boolToStr(getBool(p, "show-annexed-size"))))
	sb.WriteString(fmt.Sprintf("show-item-count: %s\n", boolToStr(getBool(p, "show-item-count"))))
	sb.WriteString(fmt.Sprintf("show-mtime: %s\n", boolToStr(getBool(p, "show-mtime"))))
	sb.WriteString(fmt.Sprintf("no-color: %s\n", boolToStr(getBool(p, "no-color"))))
	sb.WriteString(fmt.Sprintf("mouse: %s\n", boolToStr(getBool(p, "mouse"))))
	sb.WriteString(fmt.Sprintf("non-interactive: %s\n", boolToStr(getBool(p, "non-interactive"))))
	sb.WriteString(fmt.Sprintf("no-progress: %s\n", boolToStr(getBool(p, "no-progress"))))
	sb.WriteString(fmt.Sprintf("no-unicode: %s\n", boolToStr(getBool(p, "no-unicode"))))
	sb.WriteString(fmt.Sprintf("no-cross: %s\n", boolToStr(getBool(p, "no-cross"))))
	sb.WriteString(fmt.Sprintf("no-hidden: %s\n", boolToStr(getBool(p, "no-hidden"))))
	sb.WriteString(fmt.Sprintf("no-delete: %s\n", boolToStr(getBool(p, "no-delete"))))
	sb.WriteString(fmt.Sprintf("no-spawn-shell: %s\n", boolToStr(getBool(p, "no-spawn-shell"))))
	sb.WriteString(fmt.Sprintf("follow-symlinks: %s\n", boolToStr(getBool(p, "follow-symlinks"))))
	sb.WriteString(fmt.Sprintf("profiling: %s\n", boolToStr(getBool(p, "enable-profiling"))))
	sb.WriteString(fmt.Sprintf("read-from-storage: %s\n", boolToStr(getBool(p, "read-from-storage"))))
	sb.WriteString(fmt.Sprintf("db: %s\n", formatStr(getString(p, "db"))))
	sb.WriteString(fmt.Sprintf("summarize: %s\n", boolToStr(getBool(p, "summarize"))))
	sb.WriteString(fmt.Sprintf("use-si-prefix: %s\n", boolToStr(getBool(p, "si"))))
	sb.WriteString(fmt.Sprintf("no-prefix: %s\n", boolToStr(getBool(p, "no-prefix"))))
	sb.WriteString(fmt.Sprintf("show-in-kib: %s\n", boolToStr(getBool(p, "show-in-kib"))))
	sb.WriteString(fmt.Sprintf("reverse-sort: %s\n", boolToStr(getBool(p, "reverse-sort"))))
	sb.WriteString("change-cwd: false\n")
	sb.WriteString("delete-in-background: false\n")
	sb.WriteString("delete-in-parallel: false\n")
	// since, until, max-age, min-age with quoting rules: since/until quoted if non-empty? max-age/min-age not quoted?
	formatSince := func(s string) string {
		if s == "" {
			return `""`
		}
		return fmt.Sprintf("%q", s)
	}
	formatAge := func(s string) string {
		if s == "" {
			return `""`
		}
		return s
	}
	sb.WriteString(fmt.Sprintf("since: %s\n", formatSince(getString(p, "since"))))
	sb.WriteString(fmt.Sprintf("until: %s\n", formatSince(getString(p, "until"))))
	sb.WriteString(fmt.Sprintf("max-age: %s\n", formatAge(getString(p, "max-age"))))
	sb.WriteString(fmt.Sprintf("min-age: %s\n", formatAge(getString(p, "min-age"))))
	sb.WriteString(fmt.Sprintf("archive-browsing: %s\n", boolToStr(getBool(p, "archive-browsing"))))
	sb.WriteString(fmt.Sprintf("collapse-path: %s\n", boolToStr(getBool(p, "collapse-path"))))
	return os.WriteFile(path, []byte(sb.String()), 0600)
}

func boolToStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}
