func formatSize(size int64, useSI, noPrefix, showInKib bool) string {
	if noPrefix {
		return strconv.FormatInt(size, 10)
	}
	if showInKib {
		if useSI {
			v := float64(size) / 1000.0
			return fmt.Sprintf("%.1f kB", v)
		}
		v := float64(size) / 1024.0
		return fmt.Sprintf("%.1f KiB", v)
	}
	if useSI {
		if size < 1000 {
			return fmt.Sprintf("%d B", size)
		}
		units := []string{"B", "kB", "MB", "GB", "TB", "PB", "EB"}
		v := float64(size)
		exp := 0
		for v >= 1000 && exp < len(units)-1 {
			v /= 1000
			exp++
		}
		// find correct exp? Our loop divides until <1000, but need to handle exactly? For 1000, v=1.0, exp=1 => kB good.
		// Actually above loop starts with v=size, exp=0, while v>=1000, divide. For size=1000, v=1000>=1000 => v=1.0, exp=1 => "1.0 kB" good.
		// For size=999, v=999<1000 => exp=0 => but we already handled <1000 case, so not here.
		if exp == 0 {
			return fmt.Sprintf("%d B", size)
		}
		return fmt.Sprintf("%.1f %s", v, units[exp])
	}
	// binary
	if size < 1024 {
		return fmt.Sprintf("%d B", size)
	}
	units := []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	v := float64(size)
	exp := 0
	// find exp such that size < 1024^(exp+1)
	// Use integer comparison to avoid float errors? Use loop with thresholds
	thresholds := []int64{1024, 1024 * 1024, 1024 * 1024 * 1024, 1024 * 1024 * 1024 * 1024, 1024 * 1024 * 1024 * 1024 * 1024, 1024 * 1024 * 1024 * 1024 * 1024 * 1024}
	// Actually thresholds for exp: exp=1 => 1024, exp=2 => 1048576, etc.
	exp = 0
	for i, th := range thresholds {
		if size >= th {
			exp = i + 1
		} else {
			break
		}
	}
	if exp == 0 {
		return fmt.Sprintf("%d B", size)
	}
	div := float64(int64(1) << (exp * 10))
	// For exp>=7, shift overflow? But sizes won't be that large (max ~1TB, exp<=4). Good.
	// Use pow for larger? Use loop division
	v = float64(size) / div
	return fmt.Sprintf("%.1f %s", v, units[exp])
}

// Duration parsing for max-age/min-age
func parseDurationFilter(s string) (time.Duration, error) {
	if s == "" {
		return 0, fmt.Errorf("empty")
	}
	// Must match combinations of number+unit, units: y, mo, w, d, h, m, s (mo must be checked before m)
	// Reject if starts with - or contains spaces? Original rejects "-7d" and "0" (no unit)
	re := regexp.MustCompile(`^(\d+(y|mo|w|d|h|m|s))+$`)
	if !re.MatchString(s) {
		return 0, fmt.Errorf("invalid")
	}
	// Parse sequentially
	var total time.Duration
	i := 0
	for i < len(s) {
		// parse number
		j := i
		for j < len(s) && s[j] >= '0' && s[j] <= '9' {
			j++
		}
		if j == i {
			return 0, fmt.Errorf("invalid")
		}
		numStr := s[i:j]
		n, _ := strconv.Atoi(numStr)
		// parse unit
		var unit string
		if strings.HasPrefix(s[j:], "mo") {
			unit = "mo"
			j += 2
		} else {
			unit = string(s[j])
			j++
		}
		var d time.Duration
		switch unit {
		case "y":
			d = time.Duration(n) * 365 * 24 * time.Hour
		case "mo":
			d = time.Duration(n) * 30 * 24 * time.Hour
		case "w":
			d = time.Duration(n) * 7 * 24 * time.Hour
		case "d":
			d = time.Duration(n) * 24 * time.Hour
		case "h":
			d = time.Duration(n) * time.Hour
		case "m":
			d = time.Duration(n) * time.Minute
		case "s":
			d = time.Duration(n) * time.Second
		default:
			return 0, fmt.Errorf("invalid")
		}
		total += d
		i = j
	}
	return total, nil
}

// Since/until parsing
type timeFilter struct {
	hasSinceDate bool
	sinceDate time.Time // for date-only, midnight? Actually compare calendar day
	hasSinceTime bool
	sinceTime time.Time
	hasUntilDate bool
	untilDate time.Time
	hasUntilTime bool
	untilTime time.Time
}

func parseTimeFilter(sinceStr, untilStr string) (*timeFilter, error) {
	tf := &timeFilter{}
	if sinceStr != "" {
		// try RFC3339 first? Or date-only?
		if t, err := time.Parse(time.RFC3339, sinceStr); err == nil {
			tf.hasSinceTime = true
			tf.sinceTime = t
		} else if t, err := time.Parse("2006-01-02", sinceStr); err == nil {
			tf.hasSinceDate = true
			tf.sinceDate = t
		} else {
			return nil, fmt.Errorf("invalid --since value: invalid time value %q. Use RFC3339 timestamp or YYYY-MM-DD", sinceStr)
		}
	}
	if untilStr != "" {
		if t, err := time.Parse(time.RFC3339, untilStr); err == nil {
			tf.hasUntilTime = true
			tf.untilTime = t
		} else if t, err := time.Parse("2006-01-02", untilStr); err == nil {
			tf.hasUntilDate = true
			tf.untilDate = t
		} else {
			return nil, fmt.Errorf("invalid --until value: invalid time value %q. Use RFC3339 timestamp or YYYY-MM-DD", untilStr)
		}
	}
	return tf, nil
}

func (tf *timeFilter) checkSince(mtime time.Time) bool {
	if tf.hasSinceTime {
		return !mtime.Before(tf.sinceTime)
	}
	if tf.hasSinceDate {
		// calendar-day compare: include whole day => compare YYYY-MM-DD
		// Convert both to same location? Use local? Use mtime's location? Simplify: compare in local time
		// Since date is at midnight UTC? Actually parse gives UTC. Convert mtime to same?
		// We'll compare dates in local
		my := mtime.Format("2006-01-02")
		sy := tf.sinceDate.Format("2006-01-02")
		return my >= sy
	}
	return true
}
func (tf *timeFilter) checkUntil(mtime time.Time) bool {
	if tf.hasUntilTime {
		return !mtime.After(tf.untilTime)
	}
	if tf.hasUntilDate {
		my := mtime.Format("2006-01-02")
		uy := tf.untilDate.Format("2006-01-02")
		return my <= uy
	}
	return true
}

