package main

import (
	"fmt"
	"os"
	"strings"
	"syscall"
)

func showDisks(useSI, noPrefix, showInKib bool) string {
	// Header exactly
	header := "      Device      Size      Used      Free Used% Mount point\n"
	// Read /proc/mounts, filter device starting with /dev/
	data, err := os.ReadFile("/proc/mounts")
	if err != nil {
		// fallback to /etc/mtab?
		return header
	}
	lines := strings.Split(string(data), "\n")
	var out strings.Builder
	out.WriteString(header)
	for _, line := range lines {
		if strings.TrimSpace(line) == "" {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		device := fields[0]
		mount := fields[1]
		if !strings.HasPrefix(device, "/dev/") {
			continue
		}
		// statfs mount
		var st syscall.Statfs_t
		if err := syscall.Statfs(mount, &st); err != nil {
			continue
		}
		// total = Blocks * Bsize, free = Bavail * Bsize, used = total - free? Or total - Bfree? Original uses? Let's use Bavail for free (available to unprivileged), as df does? df Available is Bavail. Used = total - Bfree? Or total - Bavail? For df, Used = total - Available - Reserved? Actually df Used = (Blocks - Bfree)*Bsize? Let's check: total 1073217536000, Used 1010334003200, Available 62883532800. Total - Available = 1010334003200? 1073217536000-62883532800=1010334003200 exactly Used. So Used = total - Available (Bavail), not Bfree. Good. So free = Bavail*Bsize, used = total - free.
		total := int64(st.Blocks) * int64(st.Bsize)
		free := int64(st.Bavail) * int64(st.Bsize)
		used := total - free
		if total == 0 {
			continue
		}
		pct := int(used * 100 / total)
		sizeStr := formatSize(total, useSI, noPrefix, showInKib)
		usedStr := formatSize(used, useSI, noPrefix, showInKib)
		freeStr := formatSize(free, useSI, noPrefix, showInKib)
		// Pad sizes to 9? And pct to 5? Let's do: device left? Actually device as is, sizes padded to 9, pct padded?
		// For header alignment, we need to pad. Let's pad sizes to width 9 with %9s, pct to width 4? But earlier we deduced pct width 5. Let's use %9s for sizes and %4s for pct? That gives 2 spaces before pct for 2-digit? Actually for 89% (3 chars) padded to 4 => 1 leading => total 2 spaces (1 sep +1 pad). But observed has 3 spaces. So need %5s for pct.
		// Let's use %9s for sizes, %5s for pct? Test: size "999.5 GiB" (9) %9s => no pad. Free "58.9 GiB" (8) %9s => 1 leading. Good. Pct "89%" (3) %5s => 2 leading. Good. Then join with single spaces: device + " " + size + " " + used + " " + free + " " + pct + " " + mount
		// That gives for free "107.7 GiB" (9) + " " + "  89%" (5 with 2 leading) => "107.7 GiB   " + "89%"? That's 3 spaces. Good.
		sizeP := fmt.Sprintf("%9s", sizeStr)
		usedP := fmt.Sprintf("%9s", usedStr)
		freeP := fmt.Sprintf("%9s", freeStr)
		pctStr := fmt.Sprintf("%d%%", pct)
		pctP := fmt.Sprintf("%5s", pctStr)
		out.WriteString(fmt.Sprintf("%s %s %s %s %s %s\n", device, sizeP, usedP, freeP, pctP, mount))
	}
	return out.String()
}
