func printDepthDFS(root *Entry, maxDepth, curDepth int, useApparent, useSI, noPrefix, showInKib bool, isTTY, noColor bool, reverse bool) string {
	var out string
	// print current node
	sizeVal := formatEntrySize(root, useApparent)
	sizeStr := formatSize(sizeVal, useSI, noPrefix, showInKib)
	sizePadded := padSize(sizeStr, 9)
	name := root.Path
	if isTTY && !noColor {
		num, unit := splitNumUnit(sizeStr)
		leading := ""
		if len(sizePadded) > len(sizeStr) {
			leading = sizePadded[:len(sizePadded)-len(sizeStr)]
		}
		colored := leading + "\x1b[33;1m" + num + "\x1b[0;22m" + unit
		if root.IsDir {
			name = "\x1b[34;1m" + name + "\x1b[0;22m"
		}
		out += fmt.Sprintf("%s %s\n", colored, name)
	} else {
		out += fmt.Sprintf("%s %s\n", sizePadded, name)
	}
	if curDepth >= maxDepth {
		return out
	}
	// sort children
	children := append([]*Entry(nil), root.Children...)
	sortEntries(children, reverse)
	// For depth, sorting should be by TotalDisk? Our sortEntries uses TotalDisk and Name (basename). For depth, tie-breaker should be full path? But for children of same parent, full paths share prefix, so basename vs full path gives same order (since prefix same, comparison reduces to basename). Good. So use sortEntries.
	for _, ch := range children {
		if ch.IsDir {
			out += printDepthDFS(ch, maxDepth, curDepth+1, useApparent, useSI, noPrefix, showInKib, isTTY, noColor, reverse)
		} else {
			// file at depth curDepth+1
			if curDepth+1 <= maxDepth {
				sz := formatEntrySize(ch, useApparent)
				sStr := formatSize(sz, useSI, noPrefix, showInKib)
				sPad := padSize(sStr, 9)
				nm := ch.Path
				if isTTY && !noColor {
					num, unit := splitNumUnit(sStr)
					leading := ""
					if len(sPad) > len(sStr) {
						leading = sPad[:len(sPad)-len(sStr)]
					}
					colored := leading + "\x1b[33;1m" + num + "\x1b[0;22m" + unit
					out += fmt.Sprintf("%s %s\n", colored, nm)
				} else {
					out += fmt.Sprintf("%s %s\n", sPad, nm)
				}
			}
		}
	}
	return out
}
